<script setup lang="ts">import { ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import Button from '@/volt/Button.vue'; import InputText from '@/volt/InputText.vue'; import FormField from '@/components/ui/FormField.vue'; import { useWorkspacesStore } from '@/stores/workspaces'; const { t } = useI18n(); const name = ref(''); const workspaces = useWorkspacesStore(); const router = useRouter(); async function create() { await workspaces.create(name.value); router.push(`/w/${workspaces.activeId}/studio`) }</script>
<template><div class="flex min-h-screen items-center justify-center bg-[var(--app-bg)] p-6"><form class="surface w-full max-w-md rounded-2xl p-7 shadow-xl" @submit.prevent="create"><h1 class="text-xl font-semibold">{{ t('newWorkspace.title') }}</h1><p class="muted mt-2 text-sm">{{ t('newWorkspace.subtitle') }}</p><FormField class="mt-6" :label="t('newWorkspace.name')" required><InputText v-model="name" required /></FormField><div class="mt-5 flex justify-end gap-2"><Button variant="secondary" @click="router.back()">{{ t('common.cancel') }}</Button><Button type="submit">{{ t('common.create') }}</Button></div></form></div></template>
